import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general',
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_token(token):
    """Verify HMAC-based API token from internal services"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    service_id, signature = parts
    expected = hmac.new(SECRET_KEY.encode(), service_id.encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(expected, signature):
        return service_id
    return None

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by department and role for directory listing.
    Supports filtering by multiple fields for admin dashboard."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    token = auth_header[7:]
    caller = verify_api_token(token)
    if not caller:
        return jsonify({'error': 'invalid token'}), 403

    department = request.args.get('department', '')
    role = request.args.get('role', '')
    active_only = request.args.get('active', '1')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE active = ?"
    params = [active_only]

    if department:
        base_query += " AND department = '" + department + "'"

    if role:
        base_query += " AND role = '" + role + "'"

    try:
        db = get_db()
        results = db.execute(base_query, params).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('user_search', f'dept={department},role={role}', caller)
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    token = auth_header[7:]
    caller = verify_api_token(token)
    if not caller:
        return jsonify({'error': 'invalid token'}), 403

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()

    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
